"""The kinds of subterrain a terrain is generated from, one options class each (see ``gs.morphs.Terrain``)."""

from typing import ClassVar

from pydantic import ConfigDict

from genesis.typing import NonNegativeFloat, PositiveFloat, PositiveInt, ValidFloat

from .options import Options


class Subterrain(Options):
    """Base class of the kinds of subterrain, each generated by the function ``gs.register_subterrain`` registers.

    A user defines a kind of subterrain by subclassing this class and registering the function that fills the height
    field of a tile from its options.
    """

    # Frozen, since assigning a field skips the validators
    model_config = ConfigDict(frozen=True)

    # The name 'subterrain_types' of 'gs.morphs.Terrain' gives the kind, for the built-in kinds alone
    _NAME: ClassVar[str | None] = None


class Flat(Subterrain):
    """A flat tile at zero height."""

    _NAME = "flat_terrain"


class Fractal(Subterrain):
    """A tile of fractal noise.

    Parameters
    ----------
    levels : int, optional
        The number of octaves of the noise. Defaults to 8.
    scale : float, optional
        The amplitude of the noise in meters. Defaults to 5.0.
    """

    _NAME = "fractal_terrain"

    levels: PositiveInt = 8
    scale: ValidFloat = 5.0


class RandomUniform(Subterrain):
    """A tile of heights drawn uniformly at random on a coarse grid.

    Parameters
    ----------
    min_height : float, optional
        The lowest height in meters. Defaults to -0.1.
    max_height : float, optional
        The highest height in meters. Defaults to 0.1.
    step : float, optional
        The step between two drawable heights in meters. Defaults to 0.1.
    downsampled_scale : float, optional
        The size of a cell of the coarse grid the heights are drawn on, in meters. Defaults to 0.5.
    """

    _NAME = "random_uniform_terrain"

    min_height: ValidFloat = -0.1
    max_height: ValidFloat = 0.1
    step: PositiveFloat = 0.1
    downsampled_scale: PositiveFloat = 0.5


class Sloped(Subterrain):
    """A tile sloping along one axis.

    Parameters
    ----------
    slope : float, optional
        The rise over run of the slope. Defaults to -0.5.
    """

    _NAME = "sloped_terrain"

    slope: ValidFloat = -0.5


class PyramidSloped(Subterrain):
    """A tile sloping from its border towards its center.

    Parameters
    ----------
    slope : float, optional
        The rise over run of the slope, negative for a pit. Defaults to -0.1.
    platform_size : float, optional
        The side of the flat platform at the center of the tile in meters. Defaults to 1.0.
    """

    _NAME = "pyramid_sloped_terrain"

    slope: ValidFloat = -0.1
    platform_size: NonNegativeFloat = 1.0


class DiscreteObstacles(Subterrain):
    """A tile of rectangular obstacles of random sizes and heights.

    Parameters
    ----------
    max_height : float, optional
        The highest obstacle in meters. Defaults to 0.05.
    min_size : float, optional
        The smallest side of an obstacle in meters. Defaults to 1.0.
    max_size : float, optional
        The largest side of an obstacle in meters. Defaults to 5.0.
    num_rects : int, optional
        The number of obstacles. Defaults to 20.
    platform_size : float, optional
        The side of the flat platform at the center of the tile in meters. Defaults to 1.0.
    """

    _NAME = "discrete_obstacles_terrain"

    max_height: ValidFloat = 0.05
    min_size: PositiveFloat = 1.0
    max_size: PositiveFloat = 5.0
    num_rects: PositiveInt = 20
    platform_size: NonNegativeFloat = 1.0


class Wave(Subterrain):
    """A tile of sine waves.

    Parameters
    ----------
    num_waves : float, optional
        The number of waves across the tile. Defaults to 2.0.
    amplitude : float, optional
        The amplitude of the waves in meters. Defaults to 0.1.
    """

    _NAME = "wave_terrain"

    num_waves: ValidFloat = 2.0
    amplitude: ValidFloat = 0.1


class Stairs(Subterrain):
    """A tile of straight stairs.

    Parameters
    ----------
    step_width : float, optional
        The depth of a step in meters. Defaults to 0.75.
    step_height : float, optional
        The rise of a step in meters, negative for stairs going down. Defaults to -0.1.
    """

    _NAME = "stairs_terrain"

    step_width: PositiveFloat = 0.75
    step_height: ValidFloat = -0.1


class PyramidStairs(Subterrain):
    """A tile of stairs climbing from its border towards its center.

    Parameters
    ----------
    step_width : float, optional
        The depth of a step in meters. Defaults to 0.75.
    step_height : float, optional
        The rise of a step in meters, negative for stairs going down. Defaults to -0.1.
    platform_size : float, optional
        The side of the flat platform at the center of the tile in meters. Defaults to 1.0.
    """

    _NAME = "pyramid_stairs_terrain"

    step_width: PositiveFloat = 0.75
    step_height: ValidFloat = -0.1
    platform_size: NonNegativeFloat = 1.0


class SteppingStones(Subterrain):
    """A tile of square stones of random heights, separated by gaps.

    Parameters
    ----------
    stone_size : float, optional
        The side of a stone in meters. Defaults to 1.0.
    stone_distance : float, optional
        The gap between two stones in meters. Defaults to 0.25.
    max_height : float, optional
        The highest stone in meters. Defaults to 0.2.
    platform_size : float, optional
        The side of the flat platform at the center of the tile in meters. Defaults to 0.0.
    """

    _NAME = "stepping_stones_terrain"

    stone_size: PositiveFloat = 1.0
    stone_distance: NonNegativeFloat = 0.25
    max_height: ValidFloat = 0.2
    platform_size: NonNegativeFloat = 0.0


SUBTERRAIN_CLS_BY_NAME: dict[str, type[Subterrain]] = {
    cls._NAME: cls
    for cls in (
        Flat,
        Fractal,
        RandomUniform,
        Sloped,
        PyramidSloped,
        DiscreteObstacles,
        Wave,
        Stairs,
        PyramidStairs,
        SteppingStones,
    )
}
